import { EMPTY_OBJ } from '../constants';
import { BaseComponent, getDomSibling } from '../component';
import { Fragment } from '../create-element';
import { diffChildren } from './children';
import { diffProps, setProperty } from './props';
import { assign, isArray, removeNode, slice } from '../util';
import options from '../options';

function CatchErrorHost() {
	this._error = null;
	this._handled = false;
}

/**
 * Find the closest error boundary to a thrown error and call it
 * @param {object} error The thrown value
 * @param {VNode} vnode The vnode that threw the error that was caught (except
 * for unmounting when this parameter is the highest parent that was being
 * unmounted)
 * @param {VNode} [oldVNode]
 * @param {ErrorInfo} [errorInfo]
 */
CatchErrorHost.prototype._catchError = function (
	error,
	vnode,
	oldVNode,
	errorInfo
) {
	/** @type {Component} */
	let component,
		/** @type {ComponentType} */
		ctor;

	this._error = error;
	this._handled = false;

	for (; (vnode = vnode._parent); ) {
		if (
			typeof vnode.type == 'function' &&
			(component = vnode._component) &&
			!component._processingException
		) {
			try {
				ctor = component.constructor;

				if (ctor && ctor.getDerivedStateFromError != null) {
					component.setState(ctor.getDerivedStateFromError(this._error));
					this._handled = component._dirty;
				}

				if (component.componentDidCatch != null) {
					component.componentDidCatch(this._error, errorInfo || {});
					this._handled = component._dirty;
				}

				// This is an error boundary. Mark it as having bailed out, and whether it was mid-hydration.
				if (this._handled) {
					return (component._pendingError = component);
				}
			} catch (e) {
				this._error = e;
			}
		}
	}

	throw this._error;
};

options._catchError = CatchErrorHost.prototype._catchError.bind(
	new CatchErrorHost()
);

